import MaterialIcons from "@expo/vector-icons/MaterialIcons";
import { useRouter } from "expo-router";
import { useEffect, useMemo, useState } from "react";
import { Alert, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from "react-native";
import * as Print from "expo-print";
import * as Sharing from "expo-sharing";

import { AppHeader, EmptyState, IconButton, LoadingView, StatusPill } from "@/components/study-ui";
import { ScreenContainer } from "@/components/screen-container";
import { appTheme } from "@/lib/app-theme";
import { useStudy } from "@/lib/study-context";
import { cancelWeeklyReflectionFollowUpDueReminder, cancelWeeklyReflectionFollowUpReminder, cancelWeeklyReflectionReminder, notifyWeeklyGoalReached, notifyWeeklyReflectionFollowUpStreakBreak, scheduleWeeklyReflectionFollowUpDueReminder, scheduleWeeklyReflectionFollowUpReminder, scheduleWeeklyReflectionReminder } from "@/lib/study-reminders";
import { createWeeklyReflectionArchiveReportHtml } from "@/lib/weekly-reflection-archive-report";
import { getWeeklyReflectionArchive, getWeeklyReflectionCount, type WeeklyReflectionRange } from "@/lib/weekly-reflection-archive";
import { REFLECTION_FOCUS_AREAS } from "@/lib/weekly-reflection";
import { FOLLOW_UP_PRIORITIES, getFollowUpDueOptions, getFollowUpPostponeOptions } from "@/lib/weekly-reflection-follow-up";
import { getWeeklyReflectionInsights } from "@/lib/weekly-reflection-insights";
import { getCompletedFollowUpArchive } from "@/lib/weekly-reflection-follow-up-archive";
import { getFollowUpCompletionInsights } from "@/lib/weekly-reflection-follow-up-insights";
import { createFollowUpArchiveReportHtml } from "@/lib/weekly-reflection-follow-up-archive-report";
import { getFollowUpMonthlyGoalProgress, getFollowUpStreakBreakStatus, normalizeFollowUpMonthlyTarget, shouldNotifyFollowUpStreakBreak } from "@/lib/weekly-reflection-follow-up-monthly-goal";
import { normalizeWeeklyReflectionReminderHour, normalizeWeeklyReflectionReminderMinute, WEEKLY_REFLECTION_REMINDER_HOURS, WEEKLY_REFLECTION_REMINDER_MINUTES } from "@/lib/weekly-reflection-reminder";
import { createWeeklySummaryReportHtml } from "@/lib/weekly-summary-report";
import { getWeekStartIso } from "@/lib/subject-weekly-goals";
import type { FollowUpPriority, ReflectionFocusArea, Subject } from "@/lib/study-types";

const WEEK_MS = 7 * 24 * 60 * 60 * 1000;
const RANGES: { id: WeeklyReflectionRange; label: string }[] = [{ id: "all", label: "الكل" }, { id: "four-weeks", label: "4 أسابيع" }, { id: "three-months", label: "3 أشهر" }];

export default function WeeklySummaryScreen() {
  const router = useRouter();
  const { hydrated, lectures, reviewCards, reviewLists, subjects, getSubject, syncSettings, updateSyncSettings, weeklyReflections, saveWeeklyReflection } = useStudy();
  const [lectureGoalInput, setLectureGoalInput] = useState(String(syncSettings.weeklyLectureGoal ?? 3));
  const [reviewGoalInput, setReviewGoalInput] = useState(String(syncSettings.weeklyReviewGoal ?? 10));
  const [monthlyFollowUpGoalInput, setMonthlyFollowUpGoalInput] = useState(String(normalizeFollowUpMonthlyTarget(syncSettings.weeklyReflectionFollowUpMonthlyGoal)));
  const [reflectionInput, setReflectionInput] = useState("");
  const [reflectionRating, setReflectionRating] = useState<number>(0);
  const [reflectionFocusAreas, setReflectionFocusAreas] = useState<ReflectionFocusArea[]>([]);
  const [followUpGoalInput, setFollowUpGoalInput] = useState("");
  const [followUpCompleted, setFollowUpCompleted] = useState(false);
  const [followUpPriority, setFollowUpPriority] = useState<FollowUpPriority>("medium");
  const [followUpDueAt, setFollowUpDueAt] = useState<string | undefined>();
  const [followUpSubjectId, setFollowUpSubjectId] = useState<string | undefined>();
  const [followUpRepeatsWeekly, setFollowUpRepeatsWeekly] = useState(false);
  const [followUpReminderBusy, setFollowUpReminderBusy] = useState(false);
  const [followUpDueReminderBusy, setFollowUpDueReminderBusy] = useState(false);
  const [reflectionQuery, setReflectionQuery] = useState("");
  const [followUpArchiveQuery, setFollowUpArchiveQuery] = useState("");
  const [reflectionRange, setReflectionRange] = useState<WeeklyReflectionRange>("all");
  const [reflectionReminderBusy, setReflectionReminderBusy] = useState(false);
  const [exportingReflectionArchive, setExportingReflectionArchive] = useState(false);
  const [exportingFollowUpArchive, setExportingFollowUpArchive] = useState(false);
  const reflectionWeekStart = getWeekStartIso();
  const currentReflection = (weeklyReflections ?? []).find((reflection) => reflection.weekStart === reflectionWeekStart);
  const reflectionArchive = useMemo(() => getWeeklyReflectionArchive(weeklyReflections ?? [], reflectionQuery, 12, reflectionRange), [reflectionQuery, reflectionRange, weeklyReflections]);
  const reflectionCount = getWeeklyReflectionCount(weeklyReflections ?? []);
  const reflectionInsights = useMemo(() => getWeeklyReflectionInsights(weeklyReflections ?? []), [weeklyReflections]);
  const completedFollowUpArchive = useMemo(() => getCompletedFollowUpArchive(weeklyReflections ?? [], followUpArchiveQuery), [followUpArchiveQuery, weeklyReflections]);
  const followUpCompletionInsights = useMemo(() => getFollowUpCompletionInsights(weeklyReflections ?? []), [weeklyReflections]);
  const monthlyFollowUpProgress = useMemo(() => getFollowUpMonthlyGoalProgress(weeklyReflections ?? [], syncSettings.weeklyReflectionFollowUpMonthlyGoal), [syncSettings.weeklyReflectionFollowUpMonthlyGoal, weeklyReflections]);
  const followUpStreakBreakStatus = useMemo(() => getFollowUpStreakBreakStatus(weeklyReflections ?? []), [weeklyReflections]);
  const followUpStreakBreakNeedsReminder = shouldNotifyFollowUpStreakBreak(syncSettings.weeklyReflectionFollowUpStreakReminderEnabled, syncSettings.weeklyReflectionFollowUpStreakReminderNotifiedForWeek, followUpStreakBreakStatus);
  const followUpDueOptions = useMemo(() => getFollowUpDueOptions(), [reflectionWeekStart]);
  const followUpPostponeOptions = useMemo(() => getFollowUpPostponeOptions(followUpDueAt), [followUpDueAt]);
  const reflectionReminderHour = normalizeWeeklyReflectionReminderHour(syncSettings.weeklyReflectionReminderHour);
  const reflectionReminderMinute = normalizeWeeklyReflectionReminderMinute(syncSettings.weeklyReflectionReminderMinute);
  const summary = useMemo(() => {
    const now = Date.now(); const start = now - WEEK_MS; const previousStart = now - WEEK_MS * 2;
    const thisWeek = lectures.filter((lecture) => new Date(lecture.recordedAt).getTime() >= start);
    const previousWeek = lectures.filter((lecture) => { const time = new Date(lecture.recordedAt).getTime(); return time >= previousStart && time < start; });
    const reviewed = reviewCards.filter((card) => card.lastReviewedAt && new Date(card.lastReviewedAt).getTime() >= start);
    const storage = thisWeek.reduce((sum, lecture) => sum + (lecture.audioSizeBytes ?? 0) + (lecture.attachments ?? []).reduce((total, attachment) => total + (attachment.sizeBytes ?? 0), 0), 0);
    const tags = new Map<string, number>(); thisWeek.forEach((lecture) => (lecture.tags ?? []).forEach((tag) => tags.set(tag, (tags.get(tag) ?? 0) + 1)));
    const lists = reviewLists ?? []; return { thisWeek, previousWeek, reviewed, storage, topTags: Array.from(tags.entries()).sort((a, b) => b[1] - a[1]).slice(0, 4), activeLists: lists.length, listItems: lists.reduce((sum, list) => sum + list.lectureIds.length, 0), completedItems: lists.reduce((sum, list) => sum + list.completedLectureIds.length, 0) };
  }, [lectures, reviewCards, reviewLists]);
  const lectureGoal = syncSettings.weeklyLectureGoal ?? 3; const reviewGoal = syncSettings.weeklyReviewGoal ?? 10; const reachedGoals = summary.thisWeek.length >= lectureGoal && summary.reviewed.length >= reviewGoal; const weekKey = String(Math.floor(Date.now() / WEEK_MS));

  useEffect(() => { if (hydrated) { setReflectionInput(currentReflection?.note ?? ""); setReflectionRating(currentReflection?.rating ?? 0); setReflectionFocusAreas(currentReflection?.focusAreas ?? []); setFollowUpGoalInput(currentReflection?.followUpGoal ?? ""); setFollowUpCompleted(Boolean(currentReflection?.followUpCompleted)); setFollowUpPriority(currentReflection?.followUpPriority ?? "medium"); setFollowUpDueAt(currentReflection?.followUpDueAt); setFollowUpSubjectId(currentReflection?.followUpSubjectId); setFollowUpRepeatsWeekly(Boolean(currentReflection?.followUpRepeatsWeekly)); } }, [currentReflection?.focusAreas, currentReflection?.followUpCompleted, currentReflection?.followUpDueAt, currentReflection?.followUpGoal, currentReflection?.followUpPriority, currentReflection?.followUpRepeatsWeekly, currentReflection?.followUpSubjectId, currentReflection?.note, currentReflection?.rating, hydrated, reflectionWeekStart]);
  useEffect(() => { if (hydrated) setMonthlyFollowUpGoalInput(String(normalizeFollowUpMonthlyTarget(syncSettings.weeklyReflectionFollowUpMonthlyGoal))); }, [hydrated, syncSettings.weeklyReflectionFollowUpMonthlyGoal]);
  useEffect(() => { if (!hydrated || !syncSettings.weeklyGoalNotificationEnabled || !reachedGoals || syncSettings.weeklyGoalNotificationWeekKey === weekKey) return; updateSyncSettings({ weeklyGoalNotificationWeekKey: weekKey }); void notifyWeeklyGoalReached(); }, [hydrated, reachedGoals, syncSettings.weeklyGoalNotificationEnabled, syncSettings.weeklyGoalNotificationWeekKey, updateSyncSettings, weekKey]);
  useEffect(() => { if (!hydrated || !followUpStreakBreakNeedsReminder || !followUpStreakBreakStatus.missedWeekStart) return; void (async () => { const notified = await notifyWeeklyReflectionFollowUpStreakBreak(); if (notified) updateSyncSettings({ weeklyReflectionFollowUpStreakReminderNotifiedForWeek: followUpStreakBreakStatus.missedWeekStart }); })(); }, [followUpStreakBreakNeedsReminder, followUpStreakBreakStatus.missedWeekStart, hydrated, updateSyncSettings]);
  if (!hydrated) return <ScreenContainer><LoadingView /></ScreenContainer>;

  const lectureTrend = summary.thisWeek.length - summary.previousWeek.length;
  const saveGoals = () => { const lectureValue = Number(lectureGoalInput); const reviewValue = Number(reviewGoalInput); if (!Number.isInteger(lectureValue) || !Number.isInteger(reviewValue) || lectureValue < 1 || reviewValue < 1 || lectureValue > 99 || reviewValue > 999) { Alert.alert("قيم غير صالحة", "اختر هدفاً صحيحاً: من 1 إلى 99 محاضرة ومن 1 إلى 999 بطاقة."); return; } updateSyncSettings({ weeklyLectureGoal: lectureValue, weeklyReviewGoal: reviewValue }); Alert.alert("تم حفظ أهداف الأسبوع", "سيُحدّث المؤشر تلقائياً من محاضراتك وبطاقاتك المحلية."); };
  const saveMonthlyFollowUpGoal = () => { const target = Number(monthlyFollowUpGoalInput); if (!Number.isInteger(target) || target < 1 || target > 99) { Alert.alert("قيمة غير صالحة", "اختر هدفاً شهرياً من 1 إلى 99 خطوة مكتملة."); return; } updateSyncSettings({ weeklyReflectionFollowUpMonthlyGoal: target }); Alert.alert("تم حفظ الهدف الشهري", "سيُحدّث التقدم من خطوات المتابعة المكتملة على جهازك."); };
  const reflectionBase = { rating: reflectionRating ? reflectionRating as 1 | 2 | 3 | 4 | 5 : undefined, focusAreas: reflectionFocusAreas };
  const followUpAttributes = (completed = followUpCompleted, completedAt = currentReflection?.followUpCompletedAt) => ({ followUpGoal: followUpGoalInput, followUpCompleted: completed, followUpCompletedAt: completed ? completedAt : undefined, followUpPriority, followUpDueAt, followUpSubjectId, followUpRepeatsWeekly });
  const rescheduleFollowUpDueReminder = async (goal: string, dueAt = followUpDueAt, completed = followUpCompleted) => { if (!syncSettings.weeklyReflectionFollowUpDueReminderEnabled) return; await cancelWeeklyReflectionFollowUpDueReminder(syncSettings.weeklyReflectionFollowUpDueReminderNotificationId); const id = !completed && dueAt ? await scheduleWeeklyReflectionFollowUpDueReminder(goal, dueAt) : undefined; updateSyncSettings(id ? { weeklyReflectionFollowUpDueReminderEnabled: true, weeklyReflectionFollowUpDueReminderNotificationId: id } : { weeklyReflectionFollowUpDueReminderEnabled: false, weeklyReflectionFollowUpDueReminderNotificationId: undefined }); };
  const saveReflection = () => { saveWeeklyReflection(reflectionWeekStart, reflectionInput, { ...reflectionBase, ...followUpAttributes() }); Alert.alert("تم حفظ الملاحظة", "حُفظت ملاحظتك وتقييمك ونقاط التركيز محلياً لهذا الأسبوع."); };
  const saveFollowUpGoal = async () => { const goal = followUpGoalInput.trim(); if (!goal) { Alert.alert("أضف هدفاً صغيراً", "اكتب خطوة محددة للأسبوع التالي أولاً."); return; } saveWeeklyReflection(reflectionWeekStart, reflectionInput, { ...reflectionBase, ...followUpAttributes() }); if (syncSettings.weeklyReflectionFollowUpReminderEnabled) { await cancelWeeklyReflectionFollowUpReminder(syncSettings.weeklyReflectionFollowUpReminderNotificationId); const id = followUpCompleted ? undefined : await scheduleWeeklyReflectionFollowUpReminder(goal); updateSyncSettings(id ? { weeklyReflectionFollowUpReminderEnabled: true, weeklyReflectionFollowUpReminderNotificationId: id } : { weeklyReflectionFollowUpReminderEnabled: false, weeklyReflectionFollowUpReminderNotificationId: undefined }); } await rescheduleFollowUpDueReminder(goal); Alert.alert("تم حفظ الهدف", followUpCompleted ? "سُجل الهدف كمكتمل محلياً." : "يمكنك تعليم الهدف مكتملًا عند إنجازه."); };
  const toggleFollowUpCompleted = async () => { if (!followUpGoalInput.trim()) { Alert.alert("أضف هدفاً صغيراً", "احفظ هدف المتابعة أولاً قبل تعليمه كمكتمل."); return; } const next = !followUpCompleted; setFollowUpCompleted(next); saveWeeklyReflection(reflectionWeekStart, reflectionInput, { ...reflectionBase, ...followUpAttributes(next, next ? new Date().toISOString() : undefined) }); if (next && syncSettings.weeklyReflectionFollowUpReminderEnabled) { await cancelWeeklyReflectionFollowUpReminder(syncSettings.weeklyReflectionFollowUpReminderNotificationId); updateSyncSettings({ weeklyReflectionFollowUpReminderEnabled: false, weeklyReflectionFollowUpReminderNotificationId: undefined }); } if (next) await rescheduleFollowUpDueReminder(followUpGoalInput.trim(), followUpDueAt, true); };
  const postponeFollowUp = async (dueAt: string) => { const goal = followUpGoalInput.trim(); if (!goal) { Alert.alert("أضف هدفاً صغيراً", "احفظ هدف المتابعة أولاً قبل تأجيله."); return; } setFollowUpDueAt(dueAt); saveWeeklyReflection(reflectionWeekStart, reflectionInput, { ...reflectionBase, ...followUpAttributes(), followUpDueAt: dueAt }); await rescheduleFollowUpDueReminder(goal, dueAt); Alert.alert("تم تأجيل الاستحقاق", `الموعد الجديد: ${new Date(`${dueAt}T00:00:00`).toLocaleDateString("ar", { month: "long", day: "numeric" })}.`); };
  const toggleFollowUpReminder = async () => { if (followUpReminderBusy) return; const goal = followUpGoalInput.trim(); if (!goal || followUpCompleted) { Alert.alert("لا يوجد هدف مفتوح", followUpCompleted ? "الهدف مكتمل بالفعل، لذلك لا يحتاج إلى تذكير." : "احفظ هدف متابعة قصيراً أولاً."); return; } setFollowUpReminderBusy(true); try { if (syncSettings.weeklyReflectionFollowUpReminderEnabled) { await cancelWeeklyReflectionFollowUpReminder(syncSettings.weeklyReflectionFollowUpReminderNotificationId); updateSyncSettings({ weeklyReflectionFollowUpReminderEnabled: false, weeklyReflectionFollowUpReminderNotificationId: undefined }); return; } const id = await scheduleWeeklyReflectionFollowUpReminder(goal); if (!id) { Alert.alert("لم يُفعّل التذكير", "يلزم منح إذن التنبيهات لتفعيل تذكير هدف المتابعة."); return; } updateSyncSettings({ weeklyReflectionFollowUpReminderEnabled: true, weeklyReflectionFollowUpReminderNotificationId: id }); } finally { setFollowUpReminderBusy(false); } };
  const toggleFollowUpDueReminder = async () => { if (followUpDueReminderBusy) return; const goal = followUpGoalInput.trim(); if (!goal || !followUpDueAt || followUpCompleted) { Alert.alert("لا يمكن تفعيل التنبيه", "احفظ هدفاً مفتوحاً مع تاريخ استحقاق مستقبلي أولاً."); return; } setFollowUpDueReminderBusy(true); try { if (syncSettings.weeklyReflectionFollowUpDueReminderEnabled) { await cancelWeeklyReflectionFollowUpDueReminder(syncSettings.weeklyReflectionFollowUpDueReminderNotificationId); updateSyncSettings({ weeklyReflectionFollowUpDueReminderEnabled: false, weeklyReflectionFollowUpDueReminderNotificationId: undefined }); return; } const id = await scheduleWeeklyReflectionFollowUpDueReminder(goal, followUpDueAt); if (!id) { Alert.alert("لم يُفعّل التنبيه", "اختر تاريخاً أبعد أو امنح إذن التنبيهات لتفعيل التنبيه."); return; } updateSyncSettings({ weeklyReflectionFollowUpDueReminderEnabled: true, weeklyReflectionFollowUpDueReminderNotificationId: id }); } finally { setFollowUpDueReminderBusy(false); } };
  const toggleFocusArea = (area: ReflectionFocusArea) => setReflectionFocusAreas((current) => current.includes(area) ? current.filter((item) => item !== area) : [...current, area]);
  const exportWeeklyReport = async () => { if (Platform.OS === "web") { Alert.alert("التصدير متاح على الهاتف", "افتح التطبيق على iOS أو Android لإنشاء ملف PDF ومشاركته من جهازك."); return; } try { const result = await Print.printToFileAsync({ html: createWeeklySummaryReportHtml({ lectures, reviewCards, reviewLists, subjects, weeklyReflection: currentReflection }) }); if (await Sharing.isAvailableAsync()) await Sharing.shareAsync(result.uri, { mimeType: "application/pdf", dialogTitle: "مشاركة موجز الأسبوع" }); else Alert.alert("تم إنشاء التقرير", "أُنشئ ملف PDF، لكن المشاركة غير متاحة على هذا الجهاز."); } catch { Alert.alert("تعذر تصدير الموجز", "حاول مرة أخرى أو تحقق من مساحة جهازك."); } };
  const exportReflectionArchive = async () => { if (exportingReflectionArchive) return; if (Platform.OS === "web") { Alert.alert("التصدير متاح على الهاتف", "افتح التطبيق على iOS أو Android لإنشاء ملف PDF ومشاركته من جهازك."); return; } setExportingReflectionArchive(true); try { const filtered = getWeeklyReflectionArchive(weeklyReflections ?? [], reflectionQuery, Number.POSITIVE_INFINITY, reflectionRange); const { uri } = await Print.printToFileAsync({ html: createWeeklyReflectionArchiveReportHtml(filtered) }); if (await Sharing.isAvailableAsync()) await Sharing.shareAsync(uri, { UTI: ".pdf", mimeType: "application/pdf", dialogTitle: "مشاركة أرشيف الملاحظات" }); else Alert.alert("تم إنشاء التقرير", "أُنشئ ملف PDF، لكن المشاركة غير متاحة على هذا الجهاز."); } catch { Alert.alert("تعذر تصدير الأرشيف", "حاول مرة أخرى أو تحقق من مساحة جهازك."); } finally { setExportingReflectionArchive(false); } };
  const exportFollowUpArchive = async () => { if (exportingFollowUpArchive) return; if (Platform.OS === "web") { Alert.alert("التصدير متاح على الهاتف", "افتح التطبيق على iOS أو Android لإنشاء ملف PDF ومشاركته من جهازك."); return; } setExportingFollowUpArchive(true); try { const { uri } = await Print.printToFileAsync({ html: createFollowUpArchiveReportHtml(completedFollowUpArchive, followUpCompletionInsights, (id) => id ? getSubject(id)?.title : undefined) }); if (await Sharing.isAvailableAsync()) await Sharing.shareAsync(uri, { UTI: ".pdf", mimeType: "application/pdf", dialogTitle: "مشاركة أرشيف خطوات المتابعة" }); else Alert.alert("تم إنشاء التقرير", "أُنشئ ملف PDF، لكن المشاركة غير متاحة على هذا الجهاز."); } catch { Alert.alert("تعذر تصدير الأرشيف", "حاول مرة أخرى أو تحقق من مساحة جهازك."); } finally { setExportingFollowUpArchive(false); } };
  const toggleReflectionReminder = async () => { if (reflectionReminderBusy) return; setReflectionReminderBusy(true); try { if (syncSettings.weeklyReflectionReminderEnabled) { await cancelWeeklyReflectionReminder(syncSettings.weeklyReflectionReminderNotificationId); updateSyncSettings({ weeklyReflectionReminderEnabled: false, weeklyReflectionReminderNotificationId: undefined }); return; } const id = await scheduleWeeklyReflectionReminder(reflectionReminderHour, reflectionReminderMinute); if (!id) { Alert.alert("لم يُفعّل التذكير", "يلزم منح إذن التنبيهات لتفعيل تذكير الملاحظة الأسبوعية."); return; } updateSyncSettings({ weeklyReflectionReminderEnabled: true, weeklyReflectionReminderNotificationId: id }); } finally { setReflectionReminderBusy(false); } };
  const chooseReminderTime = async (hour: number, minute: number) => { if (reflectionReminderBusy || (hour === reflectionReminderHour && minute === reflectionReminderMinute)) return; if (!syncSettings.weeklyReflectionReminderEnabled) { updateSyncSettings({ weeklyReflectionReminderHour: hour, weeklyReflectionReminderMinute: minute }); return; } setReflectionReminderBusy(true); try { await cancelWeeklyReflectionReminder(syncSettings.weeklyReflectionReminderNotificationId); const id = await scheduleWeeklyReflectionReminder(hour, minute); updateSyncSettings(id ? { weeklyReflectionReminderHour: hour, weeklyReflectionReminderMinute: minute, weeklyReflectionReminderEnabled: true, weeklyReflectionReminderNotificationId: id } : { weeklyReflectionReminderHour: hour, weeklyReflectionReminderMinute: minute, weeklyReflectionReminderEnabled: false, weeklyReflectionReminderNotificationId: undefined }); if (!id) Alert.alert("حُفظ الوقت", "حُفظ وقت التذكير، لكن تعذر إعادة جدولته دون إذن التنبيهات."); } finally { setReflectionReminderBusy(false); } };

  return <ScreenContainer className="px-5"><AppHeader eyebrow="لقطة دراسية خاصة" title="موجز الأسبوع" action={<IconButton icon="arrow-forward" label="رجوع" onPress={() => router.back()} tone="neutral" />} /><ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
    <View style={styles.hero}><MaterialIcons name="insights" size={30} color="#C7D2FE" /><View style={styles.heroCopy}><Text style={styles.heroTitle}>تقدمك خلال آخر 7 أيام</Text><Text style={styles.heroText}>كل الأرقام محسوبة على جهازك من محاضراتك ومراجعاتك فقط.</Text></View><StatusPill label={lectureTrend > 0 ? `+${lectureTrend}` : `${lectureTrend}`} tone={lectureTrend >= 0 ? "success" : "warning"} /></View>
    <Pressable onPress={() => void exportWeeklyReport()} style={styles.exportButton}><MaterialIcons name="picture-as-pdf" size={19} color={appTheme.primary} /><Text style={styles.exportText}>تصدير الموجز PDF</Text></Pressable>
    <View style={styles.goalCard}><Heading icon="flag" color={appTheme.warning} title="أهداف الأسبوع" /><GoalRow icon="graphic-eq" title="محاضرات جديدة" current={summary.thisWeek.length} goal={lectureGoal} value={lectureGoalInput} onChange={setLectureGoalInput} /><GoalRow icon="style" title="بطاقات مراجعة" current={summary.reviewed.length} goal={reviewGoal} value={reviewGoalInput} onChange={setReviewGoalInput} /><Pressable onPress={saveGoals} style={styles.goalSave}><Text style={styles.goalSaveText}>حفظ الأهداف</Text></Pressable>{reachedGoals ? <Text style={styles.goalReached}>أحسنت، حققت هدفي الأسبوع.</Text> : null}</View>
    <View style={styles.reflectionCard}><Heading icon="edit-note" color={appTheme.violet} title="ملاحظة ختامية للأسبوع" /><Text style={styles.sectionCopy}>دوّن ما ساعدك أو ما تريد تحسينه، ثم أضف تقييماً ونقطة أو أكثر للتركيز.</Text><TextInput value={reflectionInput} onChangeText={setReflectionInput} placeholder="مثال: سأخصص جلستين لمادة الإحصاء الأسبوع المقبل." placeholderTextColor="#94A3B8" multiline maxLength={1000} textAlign="right" style={styles.reflectionInput} /><Text style={styles.microLabel}>كيف تقيّم أسبوعك؟</Text><View style={styles.ratingRow}>{[1, 2, 3, 4, 5].map((rating) => <Pressable key={rating} onPress={() => setReflectionRating(rating === reflectionRating ? 0 : rating)} style={[styles.ratingButton, rating === reflectionRating && styles.ratingButtonActive]}><MaterialIcons name="star" size={16} color={rating === reflectionRating ? "#FFFFFF" : appTheme.warning} /><Text style={[styles.ratingText, rating === reflectionRating && styles.ratingTextActive]}>{rating}</Text></Pressable>)}</View><Text style={styles.microLabel}>نقاط أركز عليها لاحقاً</Text><View style={styles.focusAreas}>{REFLECTION_FOCUS_AREAS.map((area) => <Pressable key={area.id} onPress={() => toggleFocusArea(area.id)} style={[styles.focusArea, reflectionFocusAreas.includes(area.id) && styles.focusAreaActive]}><Text style={[styles.focusAreaText, reflectionFocusAreas.includes(area.id) && styles.focusAreaTextActive]}>{area.label}</Text></Pressable>)}</View><Pressable onPress={saveReflection} style={styles.reflectionSave}><Text style={styles.reflectionSaveText}>حفظ الملاحظة</Text></Pressable><View style={styles.reminderSettings}><Text style={styles.microLabel}>وقت تذكير نهاية الأسبوع</Text><TimeChips values={WEEKLY_REFLECTION_REMINDER_HOURS} current={reflectionReminderHour} disabled={reflectionReminderBusy} getLabel={(hour) => formatReminderTime(hour, reflectionReminderMinute)} onSelect={(hour) => void chooseReminderTime(hour, reflectionReminderMinute)} /><TimeChips values={WEEKLY_REFLECTION_REMINDER_MINUTES} current={reflectionReminderMinute} disabled={reflectionReminderBusy} getLabel={(minute) => String(minute).padStart(2, "0")} onSelect={(minute) => void chooseReminderTime(reflectionReminderHour, minute)} /><Pressable disabled={reflectionReminderBusy} onPress={() => void toggleReflectionReminder()} style={[styles.reflectionReminderButton, syncSettings.weeklyReflectionReminderEnabled && styles.reflectionReminderButtonActive, reflectionReminderBusy && styles.disabled]}><MaterialIcons name={syncSettings.weeklyReflectionReminderEnabled ? "notifications-active" : "notifications-none"} size={18} color={syncSettings.weeklyReflectionReminderEnabled ? "#FFFFFF" : appTheme.violet} /><Text style={[styles.reflectionReminderText, syncSettings.weeklyReflectionReminderEnabled && styles.reflectionReminderTextActive]}>{reflectionReminderBusy ? "يجري الحفظ" : syncSettings.weeklyReflectionReminderEnabled ? `تذكير أسبوعي مفعّل — ${formatReminderTime(reflectionReminderHour, reflectionReminderMinute)}` : "تفعيل تذكير كتابة الملاحظة"}</Text></Pressable></View></View>
    <View style={styles.reflectionArchive}><View style={styles.sectionHeading}><MaterialIcons name="history" size={20} color={appTheme.violet} /><Text style={styles.sectionTitle}>أرشيف ملاحظاتك</Text><Text style={styles.reflectionCount}>{reflectionCount} أسبوع</Text></View><Text style={styles.sectionCopy}>ابحث في ملاحظاتك الختامية السابقة؛ تبقى جميعها على جهازك.</Text><View style={styles.archiveRanges}>{RANGES.map((range) => <Pressable key={range.id} onPress={() => setReflectionRange(range.id)} style={[styles.archiveRange, reflectionRange === range.id && styles.archiveRangeActive]}><Text style={[styles.archiveRangeText, reflectionRange === range.id && styles.archiveRangeTextActive]}>{range.label}</Text></Pressable>)}</View><TextInput value={reflectionQuery} onChangeText={setReflectionQuery} placeholder="ابحث في الملاحظات" placeholderTextColor="#94A3B8" textAlign="right" style={styles.archiveSearch} />{reflectionArchive.length ? reflectionArchive.map((reflection) => <View key={reflection.weekStart} style={styles.archiveNote}><Text style={styles.archiveDate}>{new Date(reflection.weekStart).toLocaleDateString("ar", { month: "long", day: "numeric", year: "numeric" })}</Text><View style={styles.archiveMeta}>{reflection.rating ? <Text style={styles.archiveRating}>★ {reflection.rating}/5</Text> : null}{(reflection.focusAreas ?? []).map((area) => <Text key={area} style={styles.archiveFocus}>{REFLECTION_FOCUS_AREAS.find((item) => item.id === area)?.label}</Text>)}</View><Text style={styles.archiveNoteText} numberOfLines={3}>{reflection.note}</Text></View>) : <Text style={styles.sectionCopy}>{reflectionQuery.trim() ? "لا توجد ملاحظة مطابقة للبحث." : "لا توجد ملاحظات ضمن الفترة المختارة."}</Text>}<Pressable disabled={exportingReflectionArchive} onPress={() => void exportReflectionArchive()} style={[styles.archiveExportButton, exportingReflectionArchive && styles.disabled]}><MaterialIcons name="picture-as-pdf" size={18} color="#FFFFFF" /><Text style={styles.archiveExportText}>{exportingReflectionArchive ? "يجري إنشاء التقرير" : "تصدير أرشيف الملاحظات PDF"}</Text></Pressable></View>
    <FollowUpGoalCard value={followUpGoalInput} completed={followUpCompleted} priority={followUpPriority} dueAt={followUpDueAt} subjectId={followUpSubjectId} repeatsWeekly={followUpRepeatsWeekly} subjects={subjects} dueOptions={followUpDueOptions} postponeOptions={followUpPostponeOptions} reminderEnabled={Boolean(syncSettings.weeklyReflectionFollowUpReminderEnabled)} reminderBusy={followUpReminderBusy} dueReminderEnabled={Boolean(syncSettings.weeklyReflectionFollowUpDueReminderEnabled)} dueReminderBusy={followUpDueReminderBusy} onChange={setFollowUpGoalInput} onSelectPriority={setFollowUpPriority} onSelectDueAt={setFollowUpDueAt} onSelectSubjectId={setFollowUpSubjectId} onToggleRepeatsWeekly={() => setFollowUpRepeatsWeekly((current) => !current)} onPostpone={(dueAt) => void postponeFollowUp(dueAt)} onToggleComplete={() => void toggleFollowUpCompleted()} onToggleReminder={() => void toggleFollowUpReminder()} onToggleDueReminder={() => void toggleFollowUpDueReminder()} onSave={() => void saveFollowUpGoal()} />
    <View style={styles.goalCard}><Heading icon="calendar-month" color={appTheme.warning} title="هدف خطوات المتابعة الشهري" /><Text style={styles.sectionCopy}>تابع عدد الخطوات الصغيرة التي أكملتها خلال {monthlyFollowUpProgress.monthLabel}؛ كل الحسابات محلية.</Text><GoalRow icon="task-alt" title="خطوات مكتملة" current={monthlyFollowUpProgress.completedCount} goal={monthlyFollowUpProgress.target} value={monthlyFollowUpGoalInput} onChange={setMonthlyFollowUpGoalInput} /><Pressable onPress={saveMonthlyFollowUpGoal} style={styles.goalSave}><Text style={styles.goalSaveText}>حفظ الهدف الشهري</Text></Pressable>{monthlyFollowUpProgress.isReached ? <Text style={styles.goalReached}>أحسنت، حققت هدفك الشهري.</Text> : <Text style={styles.sectionCopy}>يتبقى {monthlyFollowUpProgress.remainingCount} {monthlyFollowUpProgress.remainingCount === 1 ? "خطوة" : "خطوات"} للوصول إلى الهدف.</Text>}<View style={styles.reminderSettings}><Text style={styles.microLabel}>متابعة سلسلة الإنجاز</Text>{followUpStreakBreakStatus.isBroken ? <Text style={styles.sectionCopy}>توقفت السلسلة في الأسبوع السابق؛ ابدأ بخطوة صغيرة لاستعادتها.</Text> : <Text style={styles.sectionCopy}>استمر في إنجاز خطوة أسبوعية لتقوية سلسلة المتابعة.</Text>}<Pressable onPress={() => updateSyncSettings({ weeklyReflectionFollowUpStreakReminderEnabled: !syncSettings.weeklyReflectionFollowUpStreakReminderEnabled })} style={[styles.reflectionReminderButton, syncSettings.weeklyReflectionFollowUpStreakReminderEnabled && styles.reflectionReminderButtonActive]}><MaterialIcons name={syncSettings.weeklyReflectionFollowUpStreakReminderEnabled ? "notifications-active" : "notifications-none"} size={18} color={syncSettings.weeklyReflectionFollowUpStreakReminderEnabled ? "#FFFFFF" : appTheme.violet} /><Text style={[styles.reflectionReminderText, syncSettings.weeklyReflectionFollowUpStreakReminderEnabled && styles.reflectionReminderTextActive]}>{syncSettings.weeklyReflectionFollowUpStreakReminderEnabled ? "تنبيه انقطاع السلسلة مفعّل" : "تفعيل تنبيه انقطاع السلسلة"}</Text></Pressable><Text style={styles.sectionCopy}>يتحقق التطبيق من الانقطاع عند فتح موجز الأسبوع، ولا يرسل تنبيهاً مكرراً للأسبوع نفسه.</Text></View></View>
    <View style={styles.reflectionArchive}><View style={styles.sectionHeading}><MaterialIcons name="assignment-turned-in" size={20} color={appTheme.success} /><Text style={styles.sectionTitle}>أرشيف خطوات المتابعة</Text><Text style={styles.reflectionCount}>{completedFollowUpArchive.length} مكتملة</Text></View><Text style={styles.sectionCopy}>ابحث في الخطوات التي أنجزتها سابقاً؛ تبقى جميعها على جهازك.</Text><View style={styles.metrics}><View style={styles.metric}><Text style={styles.metricValue}>{followUpCompletionInsights.currentWeeklyStreak}</Text><Text style={styles.metricLabel}>سلسلة أخيرة</Text><Text style={styles.metricNote}>أسابيع متتالية</Text></View><View style={styles.metric}><Text style={styles.metricValue}>{followUpCompletionInsights.bestWeeklyStreak}</Text><Text style={styles.metricLabel}>أفضل سلسلة</Text><Text style={styles.metricNote}>أسابيع متتالية</Text></View><View style={styles.metric}><Text style={styles.metricValue}>{followUpCompletionInsights.completedCount}</Text><Text style={styles.metricLabel}>خطوات مكتملة</Text><Text style={styles.metricNote}>{followUpCompletionInsights.completionWeekCount} أسابيع</Text></View></View><TextInput value={followUpArchiveQuery} onChangeText={setFollowUpArchiveQuery} placeholder="ابحث في الخطوات المكتملة" placeholderTextColor="#94A3B8" textAlign="right" style={styles.archiveSearch} />{completedFollowUpArchive.length ? completedFollowUpArchive.map((reflection) => <View key={reflection.weekStart} style={styles.archiveNote}><Text style={styles.archiveDate}>{new Date(reflection.weekStart).toLocaleDateString("ar", { month: "long", day: "numeric", year: "numeric" })}</Text><View style={styles.archiveMeta}><Text style={styles.archiveRating}>{reflection.followUpPriority === "high" ? "أولوية عالية" : reflection.followUpPriority === "low" ? "أولوية منخفضة" : "أولوية متوسطة"}</Text>{reflection.followUpSubjectId ? <Text style={styles.archiveFocus}>{getSubject(reflection.followUpSubjectId)?.title ?? "مادة"}</Text> : null}</View><Text style={styles.archiveNoteText}>{reflection.followUpGoal}</Text></View>) : <Text style={styles.sectionCopy}>{followUpArchiveQuery.trim() ? "لا توجد خطوة مكتملة مطابقة للبحث." : "أكمل أول خطوة متابعة ليظهر سجل إنجازك هنا."}</Text>}<Pressable disabled={exportingFollowUpArchive} onPress={() => void exportFollowUpArchive()} style={[styles.archiveExportButton, exportingFollowUpArchive && styles.disabled]}><MaterialIcons name="picture-as-pdf" size={18} color="#FFFFFF" /><Text style={styles.archiveExportText}>{exportingFollowUpArchive ? "يجري إنشاء التقرير" : "تصدير أرشيف الخطوات PDF"}</Text></Pressable></View>
    <ReflectionInsightsCard insights={reflectionInsights} />
    <View style={styles.metrics}><Metric icon="graphic-eq" label="محاضرات جديدة" value={summary.thisWeek.length} note={lectureTrend === 0 ? "مثل الأسبوع السابق" : lectureTrend > 0 ? `أكثر بـ ${lectureTrend}` : `أقل بـ ${Math.abs(lectureTrend)}`} /><Metric icon="style" label="بطاقات راجعتها" value={summary.reviewed.length} note={summary.reviewed.length ? "إنجاز جيد" : "ابدأ ببطاقة واحدة"} /><Metric icon="storage" label="حجم أضيف" value={formatBytes(summary.storage)} note="صوت ومرفقات" /></View>
    <View style={styles.section}><Heading icon="playlist-add-check" color={appTheme.success} title="قوائم المراجعة" />{summary.activeLists ? <><Text style={styles.sectionCopy}>{summary.completedItems} من {summary.listItems} محاضرات مكتملة ضمن {summary.activeLists} قوائم.</Text><Track percent={summary.listItems ? summary.completedItems / summary.listItems * 100 : 0} /></> : <Text style={styles.sectionCopy}>أنشئ قائمة مراجعة من تبويب المراجعة لتتابع إنجازك هنا.</Text>}</View>
    <View style={styles.section}><Heading icon="label-outline" color={appTheme.violet} title="الوسوم البارزة هذا الأسبوع" />{summary.topTags.length ? <View style={styles.tags}>{summary.topTags.map(([tag, count]) => <View key={tag} style={styles.tag}><Text style={styles.tagText}>{tag} · {count}</Text></View>)}</View> : <Text style={styles.sectionCopy}>أضف وسوماً للمحاضرات لتظهر موضوعاتك الأكثر تكراراً.</Text>}</View>
    <View style={styles.section}><Heading icon="history" color={appTheme.primary} title="آخر المحاضرات" />{summary.thisWeek.length ? summary.thisWeek.slice(0, 5).map((lecture) => <View key={lecture.id} style={styles.lectureRow}><View style={styles.lectureIcon}><MaterialIcons name="graphic-eq" size={18} color={appTheme.primary} /></View><View style={styles.lectureCopy}><Text style={styles.lectureTitle}>{lecture.title}</Text><Text style={styles.lectureMeta}>{getSubject(lecture.subjectId)?.title ?? "مادة"} · {new Date(lecture.recordedAt).toLocaleDateString("ar")}</Text></View></View>) : <EmptyState icon="event-available" title="لم تُسجل محاضرات هذا الأسبوع" description="عند تسجيل محاضرتك التالية ستظهر في موجزك المحلي." />}</View>
  </ScrollView></ScreenContainer>;
}

function Heading({ icon, color, title }: { icon: React.ComponentProps<typeof MaterialIcons>["name"]; color: string; title: string }) { return <View style={styles.sectionHeading}><MaterialIcons name={icon} size={20} color={color} /><Text style={styles.sectionTitle}>{title}</Text></View>; }
function Track({ percent }: { percent: number }) { return <View style={styles.track}><View style={[styles.fill, { width: `${Math.min(100, percent)}%` }]} /></View>; }
function Metric({ icon, label, value, note }: { icon: React.ComponentProps<typeof MaterialIcons>["name"]; label: string; value: number | string; note: string }) { return <View style={styles.metric}><MaterialIcons name={icon} size={19} color={appTheme.primary} /><Text style={styles.metricValue}>{value}</Text><Text style={styles.metricLabel}>{label}</Text><Text style={styles.metricNote}>{note}</Text></View>; }
function FollowUpGoalCard({ value, completed, priority, dueAt, subjectId, repeatsWeekly, subjects, dueOptions, postponeOptions, reminderEnabled, reminderBusy, dueReminderEnabled, dueReminderBusy, onChange, onSelectPriority, onSelectDueAt, onSelectSubjectId, onToggleRepeatsWeekly, onPostpone, onToggleComplete, onToggleReminder, onToggleDueReminder, onSave }: { value: string; completed: boolean; priority: FollowUpPriority; dueAt?: string; subjectId?: string; repeatsWeekly: boolean; subjects: Subject[]; dueOptions: ReturnType<typeof getFollowUpDueOptions>; postponeOptions: ReturnType<typeof getFollowUpPostponeOptions>; reminderEnabled: boolean; reminderBusy: boolean; dueReminderEnabled: boolean; dueReminderBusy: boolean; onChange: (value: string) => void; onSelectPriority: (value: FollowUpPriority) => void; onSelectDueAt: (value?: string) => void; onSelectSubjectId: (value?: string) => void; onToggleRepeatsWeekly: () => void; onPostpone: (value: string) => void; onToggleComplete: () => void; onToggleReminder: () => void; onToggleDueReminder: () => void; onSave: () => void }) { return <View style={styles.section}><Heading icon="task-alt" color={appTheme.success} title="خطوة صغيرة للأسبوع التالي" /><Text style={styles.sectionCopy}>حوّل ملاحظتك إلى إجراء واحد واضح يمكنك إنجازه ومتابعته محلياً.</Text><TextInput value={value} onChangeText={onChange} placeholder="مثال: أراجع 15 دقيقة من الفصل الأول" placeholderTextColor="#94A3B8" textAlign="right" maxLength={140} style={styles.archiveSearch} /><Text style={styles.microLabel}>المادة المرتبطة</Text><View style={styles.focusAreas}><Pressable onPress={() => onSelectSubjectId(undefined)} style={[styles.focusArea, !subjectId && styles.focusAreaActive]}><Text style={[styles.focusAreaText, !subjectId && styles.focusAreaTextActive]}>دون مادة</Text></Pressable>{subjects.map((subject) => <Pressable key={subject.id} onPress={() => onSelectSubjectId(subject.id)} style={[styles.focusArea, subjectId === subject.id && styles.focusAreaActive]}><Text style={[styles.focusAreaText, subjectId === subject.id && styles.focusAreaTextActive]}>{subject.title}</Text></Pressable>)}</View><Text style={styles.microLabel}>الأولوية</Text><View style={styles.focusAreas}>{FOLLOW_UP_PRIORITIES.map((item) => <Pressable key={item.id} onPress={() => onSelectPriority(item.id)} style={[styles.focusArea, priority === item.id && styles.focusAreaActive]}><Text style={[styles.focusAreaText, priority === item.id && styles.focusAreaTextActive]}>{item.label}</Text></Pressable>)}</View><Text style={styles.microLabel}>تاريخ الاستحقاق</Text><View style={styles.focusAreas}>{dueOptions.map((option) => <Pressable key={option.label} onPress={() => onSelectDueAt(option.dueAt)} style={[styles.focusArea, dueAt === option.dueAt && styles.focusAreaActive]}><Text style={[styles.focusAreaText, dueAt === option.dueAt && styles.focusAreaTextActive]}>{option.label}</Text></Pressable>)}</View>{value.trim() ? <Pressable onPress={onToggleRepeatsWeekly} style={[styles.focusArea, repeatsWeekly && styles.focusAreaActive]}><Text style={[styles.focusAreaText, repeatsWeekly && styles.focusAreaTextActive]}>{repeatsWeekly ? "تكرار أسبوعي مفعّل" : "تكرار هذه الخطوة كل أسبوع"}</Text></Pressable> : null}{value.trim() && !completed ? <><Text style={styles.microLabel}>تأجيل سريع</Text><View style={styles.focusAreas}>{postponeOptions.map((option) => <Pressable key={option.label} onPress={() => onPostpone(option.dueAt)} style={styles.focusArea}><Text style={styles.focusAreaText}>{option.label}</Text></Pressable>)}</View></> : null}{value.trim() ? <Pressable onPress={onToggleComplete} style={[styles.focusArea, completed && styles.focusAreaActive]}><Text style={[styles.focusAreaText, completed && styles.focusAreaTextActive]}>{completed ? "تم إنجاز الخطوة" : "تعليم الخطوة كمكتملة"}</Text></Pressable> : null}<Pressable disabled={dueReminderBusy} onPress={onToggleDueReminder} style={[styles.reflectionReminderButton, dueReminderEnabled && styles.reflectionReminderButtonActive, dueReminderBusy && styles.disabled]}><MaterialIcons name={dueReminderEnabled ? "event-available" : "event"} size={18} color={dueReminderEnabled ? "#FFFFFF" : appTheme.violet} /><Text style={[styles.reflectionReminderText, dueReminderEnabled && styles.reflectionReminderTextActive]}>{dueReminderBusy ? "يجري الحفظ" : dueReminderEnabled ? "تنبيه الاستحقاق مفعّل" : "تفعيل تنبيه قبل الاستحقاق"}</Text></Pressable><Pressable disabled={reminderBusy} onPress={onToggleReminder} style={[styles.reflectionReminderButton, reminderEnabled && styles.reflectionReminderButtonActive, reminderBusy && styles.disabled]}><MaterialIcons name={reminderEnabled ? "notifications-active" : "notifications-none"} size={18} color={reminderEnabled ? "#FFFFFF" : appTheme.violet} /><Text style={[styles.reflectionReminderText, reminderEnabled && styles.reflectionReminderTextActive]}>{reminderBusy ? "يجري الحفظ" : reminderEnabled ? "تذكير منتصف الأسبوع مفعّل" : "تفعيل تذكير منتصف الأسبوع"}</Text></Pressable><Pressable onPress={onSave} style={styles.archiveExportButton}><MaterialIcons name="save" size={18} color="#FFFFFF" /><Text style={styles.archiveExportText}>حفظ هدف المتابعة</Text></Pressable></View>; }
function ReflectionInsightsCard({ insights }: { insights: ReturnType<typeof getWeeklyReflectionInsights> }) { const leadingLabel = insights.leadingFocus ? REFLECTION_FOCUS_AREAS.find((area) => area.id === insights.leadingFocus)?.label : "لا توجد بيانات"; return <View style={styles.section}><Heading icon="query-stats" color={appTheme.violet} title="مؤشرات ملاحظاتك" /><View style={styles.metrics}><View style={styles.metric}><Text style={styles.metricValue}>{insights.averageRating ? `${insights.averageRating}/5` : "—"}</Text><Text style={styles.metricLabel}>متوسط التقييم</Text><Text style={styles.metricNote}>{insights.ratedCount} أسابيع مقيمة</Text></View><View style={styles.metric}><Text style={styles.metricValue}>{leadingLabel}</Text><Text style={styles.metricLabel}>أبرز نقطة تركيز</Text><Text style={styles.metricNote}>{insights.leadingFocusCount} مرات</Text></View><View style={styles.metric}><Text style={styles.metricValue}>{insights.followUpGoalCount ? `${insights.followUpCompletionPercent}%` : "—"}</Text><Text style={styles.metricLabel}>إنجاز الخطوات</Text><Text style={styles.metricNote}>{insights.followUpCompletedCount}/{insights.followUpGoalCount} مكتملة</Text></View></View>{insights.followUpGoalCount ? <><Text style={styles.microLabel}>إنجاز الخطوات بحسب الأولوية</Text><View style={styles.focusAreas}>{insights.followUpPriorityBreakdown.map((item) => <View key={item.priority} style={styles.focusArea}><Text style={styles.focusAreaText}>{item.priority === "high" ? "عالية" : item.priority === "medium" ? "متوسطة" : "منخفضة"} · {item.completed}/{item.total} ({item.percent}%)</Text></View>)}</View></> : null}{insights.trend.length ? <><Text style={styles.sectionCopy}>اتجاه آخر {insights.trend.length} أسابيع مكتوبة</Text><View style={styles.tags}>{insights.trend.map((item) => <View key={item.weekStart} style={styles.tag}><Text style={styles.tagText}>{item.label} · {item.rating ? `★ ${item.rating}/5` : "دون تقييم"}</Text></View>)}</View></> : <Text style={styles.sectionCopy}>احفظ أول ملاحظة مع تقييم لتظهر مؤشراتك هنا.</Text>}</View>; }
function GoalRow({ icon, title, current, goal, value, onChange }: { icon: React.ComponentProps<typeof MaterialIcons>["name"]; title: string; current: number; goal: number; value: string; onChange: (value: string) => void }) { return <View style={styles.goalRow}><MaterialIcons name={icon} size={19} color={appTheme.primary} /><View style={styles.goalCopy}><View style={styles.goalLabels}><Text style={styles.goalTitle}>{title}</Text><Text style={styles.goalProgress}>{current}/{goal}</Text></View><Track percent={current / goal * 100} /></View><TextInput value={value} onChangeText={onChange} keyboardType="number-pad" maxLength={3} textAlign="center" style={styles.goalInput} /></View>; }
function TimeChips({ values, current, disabled, getLabel, onSelect }: { values: readonly number[]; current: number; disabled: boolean; getLabel: (value: number) => string; onSelect: (value: number) => void }) { return <View style={styles.reminderChips}>{values.map((value) => <Pressable key={value} disabled={disabled} onPress={() => onSelect(value)} style={[styles.reminderChip, current === value && styles.reminderChipActive, disabled && styles.disabled]}><Text style={[styles.reminderChipText, current === value && styles.reminderChipTextActive]}>{getLabel(value)}</Text></Pressable>)}</View>; }
function formatBytes(bytes: number) { if (!bytes) return "0 بايت"; const units = ["بايت", "ك.ب", "م.ب", "ج.ب"]; const index = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1); return `${(bytes / 1024 ** index).toFixed(index ? 1 : 0)} ${units[index]}`; }
function formatReminderTime(hour: number, minute: number) { return new Date(2026, 0, 1, hour, minute).toLocaleTimeString("ar", { hour: "numeric", minute: "2-digit" }); }

